import{_ as o,o as t,c as r,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Crimson/SeaStore Meeting 2023-03-08","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore Meeting 2023-03-08","date":"2023-03-08T00:00:00.000Z","updated":"2023-03-09T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH 算法","可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","Bluestore","Bluefs","Rocksdb","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","纠错编码","复制","快照","克隆","虚拟化","云计算","存储"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Crimson_SeaStore_Meeting_2023-03-08.md","filePath":"posts/2023/Ceph_Crimson_SeaStore_Meeting_2023-03-08.md","lastUpdated":1780459816000}'),i={name:"posts/2023/Ceph_Crimson_SeaStore_Meeting_2023-03-08.md"};function n(a,e,l,d,c,g){return t(),r("div",null,[...e[0]||(e[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间：</strong> 2023-03-08 <strong>参会人员：</strong> [列出参会人员]</p><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>个人工作更新</strong></p><ul><li><strong>Junction:</strong> 正在处理 <code>classic scrub</code> 和 <code>Crimson scrub</code>，同时更新了 <code>grain cache</code> 的最终版本，并关注 <code>max application size</code> 的 bug 问题。本周将重点审查 <code>lba3 optimization</code>，并计划在未来几周内投入更多精力到 <code>multiple messenger</code> 项目中。</li><li><strong>Harsh:</strong> 报告了在配置 Crimson 镜像集群时遇到的问题，确认问题与 reef build 相关，而非 Crimson 本身。</li><li><strong>Kevin:</strong> 完成了垂直系统修改和 CN storm 系统的安装测试，并请求团队进行审查。</li><li><strong>Rocky:</strong> 提到上周的 PR 主要关于 self volume 和 surveillance，Adam King 正在审查中。</li><li><strong>[其他人员]:</strong> 汇报了各自的工作进展和计划。</li></ul></li><li><p><strong>讨论文档：</strong></p><ul><li><strong>Joyhound</strong> 提出的文档关于在 systore 中实现热数据缓存功能，讨论了设计原则，包括利用应用程序访问模式的局部性，以及数据和元数据的访问模式差异。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li><strong>关于热数据缓存的讨论：</strong> 团队深入讨论了 Joyhound 的文档，涉及缓存策略、数据局部性、以及如何与现有 tiering 系统集成。建议将缓存策略设计为可插拔的。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li><strong>实施计划：</strong> 首先实现读取时的数据提升功能，然后独立考虑不同的驱逐策略。</li><li><strong>文档更新：</strong> Joyhound 将根据会议反馈更新文档，增加更多细节和设计考虑。</li></ul><p><strong>会议结束：</strong> 会议在讨论完所有议题后结束，团队成员被鼓励继续推进各自的工作，并期待下一次会议的更新。</p><p><strong>备注：</strong> 会议中提到了一些技术细节和特定术语，如 <code>LBA tree</code>、<code>tiering implementation</code>、<code>eviction policy</code> 等，这些内容对于理解会议内容和后续行动非常重要。</p>',10)])])}const _=o(i,[["render",n]]);export{u as __pageData,_ as default};
